  "<h2>📊 Tagesbericht – Tag {0}</h2>\n    <div style=\"font-size:30px;color:var(--manager);letter-spacing:4px;margin:4px 0 2px\" aria-label=\"{1} von 5 Sternen\">{2}</div>\n    <p style=\"margin:0 0 10px;color:var(--muted)\">{3} · Durchstarts {4} · Ausweichlandungen {5}</p>\n    <div class=\"report-grid\">\n      <div><span>Umsatz</span><b>{6}</b></div>\n      <div><span>Betriebskosten</span><b>{7}</b></div>\n      <div><span>Ergebnis</span><b style=\"color:{8}\">{9}</b></div>\n      <div><span>Bewegungen</span><b>{10}</b></div>\n      <div><span>Passagiere</span><b>{11}</b></div>\n      <div><span>Pünktlichkeit</span><b>{12} %</b></div>\n      <div><span>Investitionen</span><b>{13}</b></div>\n      <div><span>Vorfälle</span><b>{14}</b></div>\n      <div><span>Ansehen</span><b>{15}/100</b></div>\n      {16}\n    </div>\n    {17}\n    {18}\n    {19}\n    {20}\n    {21}\n    {22}\n    <div class=\"modal-acts\"><button class=\"btn btn-primary\" data-close-modal>Weiter</button></div>": "<h2>📊 Daily Report – Day {0}</h2>\n    <div style=\"font-size:30px;color:var(--manager);letter-spacing:4px;margin:4px 0 2px\" aria-label=\"{1} of 5 stars\">{2}</div>\n    <p style=\"margin:0 0 10px;color:var(--muted)\">{3} · Go-arounds {4} · Diversions {5}</p>\n    <div class=\"report-grid\">\n      <div><span>Revenue</span><b>{6}</b></div>\n      <div><span>Operating costs</span><b>{7}</b></div>\n      <div><span>Result</span><b style=\"color:{8}\">{9}</b></div>\n      <div><span>Movements</span><b>{10}</b></div>\n      <div><span>Passengers</span><b>{11}</b></div>\n      <div><span>Punctuality</span><b>{12}%</b></div>\n      <div><span>Investments</span><b>{13}</b></div>\n      <div><span>Incidents</span><b>{14}</b></div>\n      <div><span>Reputation</span><b>{15}/100</b></div>\n      {16}\n    </div>\n    {17}\n    {18}\n    {19}\n    {20}\n    {21}\n    {22}\n    <div class=\"modal-acts\"><button class=\"btn btn-primary\" data-close-modal>Continue</button></div>",
