  "<div class=\"ms-card ms-role r-{0}\"><div class=\"ms-img\" style=\"background-image:url({1})\"></div>\n    <div class=\"ms-body\"><div class=\"ms-h\">{2} {3}</div>\n    <div class=\"ms-sec\">Deine Aufgaben</div><ul>{4}</ul>\n    <div class=\"ms-auto\">⚙️ {5}</div></div></div>": "<div class=\"ms-card ms-role r-{0}\"><div class=\"ms-img\" style=\"background-image:url({1})\"></div>\n    <div class=\"ms-body\"><div class=\"ms-h\">{2} {3}</div>\n    <div class=\"ms-sec\">Your tasks</div><ul>{4}</ul>\n    <div class=\"ms-auto\">⚙️ {5}</div></div></div>",
