  "\n      <div class=\"rail-head\">\n        <div class=\"rail-title\">{0} Flugstreifen{1}</div>\n        <div class=\"seg\" id=\"rl-filter\" title=\"Filter: nur Landungen, beide oder nur Starts\"><button data-f=\"arr\">{2} An</button><button data-f=\"both\">Beide</button><button data-f=\"dep\">{3} Ab</button></div>\n        <button class=\"rl-tg\" id=\"rl-spacing\" title=\"Reihenfolge per Drag &amp; Drop – Anflugfreigaben, Geschwindigkeit und Lücken für Starts passen sich automatisch an\"><span class=\"switch\"></span>Auto-Staffelung</button>\n        <button class=\"rl-tg\" id=\"rl-gauto\" title=\"Rollverkehr (Pushback, Rollen, Kreuzen) automatisch – du kümmerst dich nur um Luftraum und Piste\"><span class=\"switch\"></span>Rollverkehr auto</button>\n        <span id=\"rl-sort\"></span>\n        <span class=\"rl-legend\"><span><i style=\"background:{4}\"></i>Landung</span><span><i style=\"background:{5}\"></i>frei</span><span><i style=\"background:{6}\"></i>Start</span><span><i style=\"background:{7}\"></i>frei</span></span>\n        <button class=\"mini\" id=\"rl-min\" title=\"Leiste verkleinern\">▾</button>\n      </div>\n      <div class=\"rail-lanes\" id=\"rl-lanes\">\n        <div class=\"lane\" data-lane=\"arr\"><div class=\"lane-h\"><span>{8} Landungen</span><span class=\"cnt\" id=\"rl-c-arr\">0</span><small>links = zuerst · ziehen zum Umsortieren</small></div><div class=\"lane-cards\" id=\"rl-arr\"></div></div>\n        <div class=\"lane\" data-lane=\"dep\"><div class=\"lane-h\"><span>{9} Starts</span><span class=\"cnt\" id=\"rl-c-dep\">0</span><small>links = zuerst</small></div><div class=\"lane-cards\" id=\"rl-dep\"></div></div>\n      </div>": "\n      <div class=\"rail-head\">\n        <div class=\"rail-title\">{0} Flight strips{1}</div>\n        <div class=\"seg\" id=\"rl-filter\" title=\"Filter: arrivals only, both or departures only\"><button data-f=\"arr\">{2} Arr</button><button data-f=\"both\">Both</button><button data-f=\"dep\">{3} Dep</button></div>\n        <button class=\"rl-tg\" id=\"rl-spacing\" title=\"Set the order by drag &amp; drop – approach clearances, speeds and departure gaps adjust automatically\"><span class=\"switch\"></span>Auto-spacing</button>\n        <button class=\"rl-tg\" id=\"rl-gauto\" title=\"Ground traffic (pushback, taxiing, crossings) runs automatically – you only handle the airspace and runway\"><span class=\"switch\"></span>Auto ground</button>\n        <span id=\"rl-sort\"></span>\n        <span class=\"rl-legend\"><span><i style=\"background:{4}\"></i>Landing</span><span><i style=\"background:{5}\"></i>cleared</span><span><i style=\"background:{6}\"></i>Take-off</span><span><i style=\"background:{7}\"></i>cleared</span></span>\n        <button class=\"mini\" id=\"rl-min\" title=\"Minimise bar\">▾</button>\n      </div>\n      <div class=\"rail-lanes\" id=\"rl-lanes\">\n        <div class=\"lane\" data-lane=\"arr\"><div class=\"lane-h\"><span>{8} Arrivals</span><span class=\"cnt\" id=\"rl-c-arr\">0</span><small>left = first · drag to reorder</small></div><div class=\"lane-cards\" id=\"rl-arr\"></div></div>\n        <div class=\"lane\" data-lane=\"dep\"><div class=\"lane-h\"><span>{9} Departures</span><span class=\"cnt\" id=\"rl-c-dep\">0</span><small>left = first</small></div><div class=\"lane-cards\" id=\"rl-dep\"></div></div>\n      </div>",
  "⛈️ Umweg-Anfragen genehmigt jetzt der Kollege": "⛈️ Your colleague now approves weather deviation requests",
